#[cfg(test)]
mod tests {
    use super::SHORT;

    #[test]
    fn short_lines_are_sorted_registered_and_plain() {
        assert!(SHORT.windows(2).all(|w| w[0].0 < w[1].0), "sorted, unique");
        for (name, line) in SHORT {
            assert!(victory_core::settings::info(name).is_some(), "{name} is not registered");
            assert!(line.is_ascii() && !line.contains("VICTORY_"), "{name}: {line}");
        }
    }
}
